#!/usr/bin/env python3
"""Decode /proc/net/tcp{,6} to confirm each port listens only on 127.0.0.1."""
import socket
import struct

WANT = {6379, 6380, 6381, 26379, 26380, 26381}
LISTEN = "0A"
found = {}

for path, v6 in (("/proc/net/tcp", False), ("/proc/net/tcp6", True)):
    try:
        lines = open(path).read().splitlines()[1:]
    except FileNotFoundError:
        continue
    for line in lines:
        f = line.split()
        if f[3] != LISTEN:
            continue
        hexaddr, hexport = f[1].split(":")
        port = int(hexport, 16)
        if port not in WANT:
            continue
        if v6:
            raw = bytes.fromhex(hexaddr)
            # /proc stores each 32-bit word little-endian
            raw = b"".join(raw[i:i + 4][::-1] for i in range(0, 16, 4))
            ip = socket.inet_ntop(socket.AF_INET6, raw)
        else:
            ip = socket.inet_ntoa(struct.pack("<I", int(hexaddr, 16)))
        found.setdefault(port, set()).add(ip)

ok = True
for port in sorted(WANT):
    ips = found.get(port, set())
    good = ips == {"127.0.0.1"}
    ok &= good
    print(f"{port}: {sorted(ips) or 'NOT LISTENING'} {'OK' if good else 'UNEXPECTED'}")

print("\nall six bound to 127.0.0.1 only" if ok else "\nPROBLEM: unexpected binding")

